static int checks=0;
static void check(bool value,const std::string& why){++checks;if(!value)throw std::runtime_error(why);}
static V json(const std::string& s){V v;if(!arkjson::parse(s,v))throw std::runtime_error(s);return v;}
static const V& get(const V& v,const char* key){static V none;const auto* p=v.find(key);return p?*p:none;}
static V call(AgentSession& s,const char* tool,V a){a.set("expected_revision",V::makeNum(double(s.revision)));auto r=s.call(tool,a);check(!get(r,"isError").b,r.dump());return get(r,"structuredContent");}
static V variants(AgentSession& s,const std::string& args){return call(s,"design_variants",json(args));}
static void commit(AgentSession& s,const V& preview){V a=V::makeObj();a.set("candidate_id",get(preview,"candidate_id"));call(s,"doc_apply",a);}
